-- Visitor counter & visitor location statistics (SUVADI Digital Library)
--
-- Safe to run more than once: only creates the two new tables and their indexes
-- if they do not exist yet. No existing table, column or record is changed.
-- Applied automatically at backend start-up (backend/analytics.js), or by hand:
--   psql -h <host> -U <user> -d suvadi -f backend/db/migrations/001_visitor_analytics.sql
--
-- IDs are generated by the backend (crypto.randomUUID), so no PostgreSQL extension
-- is needed. Only city / state / country are kept: no street, locality or coordinates.

-- One row per browser (visitor), identified by the browser's random visitor ID
CREATE TABLE IF NOT EXISTS site_visits (
  id           UUID PRIMARY KEY,
  session_id   VARCHAR(64)  NOT NULL UNIQUE,
  visited_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ip           VARCHAR(64),
  country      VARCHAR(100),
  country_code VARCHAR(8),
  region       VARCHAR(150),
  city         VARCHAR(150)
);

-- One row per visitor per IST calendar day (the UNIQUE pair prevents double counting)
CREATE TABLE IF NOT EXISTS site_daily_visits (
  id         UUID PRIMARY KEY,
  session_id VARCHAR(64) NOT NULL REFERENCES site_visits (session_id) ON DELETE CASCADE,
  date       DATE        NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT site_daily_visits_session_date_key UNIQUE (session_id, date)
);

-- session_id is already indexed by its UNIQUE constraints (site_visits.session_id and
-- the leading column of (session_id, date)); these cover the statistics queries.
CREATE INDEX IF NOT EXISTS site_daily_visits_date_idx ON site_daily_visits (date);
CREATE INDEX IF NOT EXISTS site_visits_country_idx    ON site_visits (country);
CREATE INDEX IF NOT EXISTS site_visits_city_idx       ON site_visits (city);
